When scan files, some resource loaders' `get_resource_script_class` will be called:
```
String ResourceLoader::get_resource_script_class(const String &p_path) {
	String local_path = _validate_local_path(p_path);

	for (int i = 0; i < loader_count; i++) {
                // Notice by me: 
                // here does not respect loader's _get_recognized_extensions() or _get_resource_type(), is it a bug?
		String result = loader[i]->get_resource_script_class(local_path);
		if (!result.is_empty()) {
			return result;
		}
	}

	return "";
}
```
Meanwhile I have a custom loader which will return always `GDMapperGraph` by `_get_resource_script_class` because I think engine will respect my `_get_recognized_extensions() `:
```
@tool
extends ResourceFormatLoader
class_name ResourceFormatLoaderGDMapperGraph

func _get_recognized_extensions() -> PackedStringArray:
	return ["gdmappergraph"]

@warning_ignore("unused_parameter")
func _get_resource_type(path: String) -> String:
	return "Resource" # ------------------------ Maybe I should check file extension according to documentation...

@warning_ignore("unused_parameter")
func _get_resource_script_class(path: String) -> String:
	return "GDMapperGraph" # ------------------------- Still need check file extension?

func _handles_type(type: StringName) -> bool:
	return ClassDB.is_parent_class(type, "Resource")

@warning_ignore("unused_parameter")
func _load(path: String, original_path: String, use_sub_threads: bool, cache_mode: int) -> Variant:
	if not FileAccess.file_exists(path):
		return ERR_FILE_NOT_FOUND

	var res = GDMapperGraph.new()
	res.load(path)
	return res
```

